#[inductive(initialize)]
fn initialize_inductive(post: Self, backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
    assert forall |i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        // post.producer = Idle(0), post.consumer = Idle(0) -> is_checked_out = false
        // post.head = 0, post.tail = 0 -> in_active_range = false for all i
        // storage has all cells uninit (from require)
        assert(!post.in_active_range(i)) by {
            // head == tail == 0 means empty range
            assert(post.head == 0nat);
            assert(post.tail == 0nat);
        };
    };
}
#[inductive(produce_start)]
fn produce_start_inductive(pre: Self, post: Self) {
    let tail = pre.producer.get_Idle_0();
    let next_tail = Self::inc_wrap(tail, pre.len());
    let head = pre.head;
    assert forall |i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == tail {
            // is_checked_out_post(tail) = true because producer is now Producing(tail)
            assert(post.producer == ProducerState::Producing(tail));
            assert(post.is_checked_out(tail));
        } else {
            // producer_pre = Idle(tail) so never Producing(i) for any i
            // consumer unchanged -> is_checked_out same
            // head/tail fields unchanged -> in_active_range same
            // storage same (only tail was removed)
            assert(pre.valid_storage_at_idx(i));
            assert(post.is_checked_out(i) == pre.is_checked_out(i)) by {
                assert(pre.producer == ProducerState::Idle(tail));
                assert(post.producer == ProducerState::Producing(tail));
                assert(post.consumer == pre.consumer);
                // pre.producer != Producing(i) (it's Idle), post.producer != Producing(i) (i != tail)
                // consumer same
            };
            assert(post.in_active_range(i) == pre.in_active_range(i)) by {
                assert(post.head == pre.head);
                assert(post.tail == pre.tail);
            };
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i)) by {
                assert(i != tail);
            };
            if !post.is_checked_out(i) {
                assert(post.storage.index(i) == pre.storage.index(i)) by {
                    assert(i != tail);
                };
            }
        }
    };
}
#[inductive(produce_end)]
fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let tail = pre.producer.get_Producing_0();
    let next_tail = Self::inc_wrap(tail, pre.len());
    let len = pre.len();
    // Key: next_tail != pre.head (from not_overlapping)
    let head = pre.head;
    assert(next_tail != head) by {
        match pre.consumer {
            ConsumerState::Idle(h) => {
                assert(pre.not_overlapping());
                assert(h == head);
            }
            ConsumerState::Consuming(h) => {
                assert(pre.not_overlapping());
                assert(h == head);
            }
        }
    };
    assert forall |i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == tail {
            // is_checked_out_post(tail): producer_post = Idle(next_tail), consumer_post = consumer_pre
            // consumer_pre != Consuming(tail) from not_overlapping
            assert(!post.is_checked_out(tail)) by {
                assert(post.producer == ProducerState::Idle(next_tail));
                assert(post.consumer == pre.consumer);
                // consumer_pre != Consuming(tail) from not_overlapping_pre
                assert(pre.not_overlapping());
                match pre.consumer {
                    ConsumerState::Idle(_h) => {}
                    ConsumerState::Consuming(h) => {
                        // not_overlapping: h != tail
                        assert(h != tail);
                    }
                }
            };
            assert(post.in_active_range(tail)) by {
                // post.head = head, post.tail = next_tail
                // next_tail != head (proved above)
                // Case analysis on inc_wrap
                assert(post.head == head);
                assert(post.tail == next_tail);
                assert(0 <= head < len);
                assert(0 <= tail < len);
                if tail + 1 == len {
                    // next_tail = 0, head > 0 (since next_tail != head)
                    assert(next_tail == 0nat);
                    assert(head > 0nat);
                    // post range: head > 0 = next_tail, else branch: i >= head || i < 0
                    // tail = len-1 >= head (since head < len = tail+1)
                    assert(tail >= head);
                } else {
                    // next_tail = tail+1
                    assert(next_tail == tail + 1);
                    // head != tail+1
                    if head <= next_tail {
                        // head <= tail+1 and head != tail+1, so head <= tail
                        assert(head <= tail);
                    } else {
                        // head > tail+1 > tail, so post range: else branch
                        // tail >= head? No, but tail < tail+1, which is fine
                    }
                }
            };
        } else {
            assert(pre.valid_storage_at_idx(i));
            assert(post.is_checked_out(i) == pre.is_checked_out(i)) by {
                assert(pre.producer == ProducerState::Producing(tail));
                assert(post.producer == ProducerState::Idle(next_tail));
                assert(post.consumer == pre.consumer);
                // pre.producer == Producing(i) iff i == tail; i != tail so false
                // post.producer is Idle, so never Producing(i)
                // consumer same
            };
            assert(post.in_active_range(i) == pre.in_active_range(i)) by {
                // head unchanged, tail changes from tail_val to next_tail
                // for i != tail_val, active range membership same
                assert(post.head == head);
                assert(post.tail == next_tail);
                assert(pre.tail == tail);
                assert(next_tail != head);
                assert(i != tail);
                assert(0 <= i < len);
                assert(0 <= tail < len);
                assert(0 <= head < len);
                if tail + 1 == len {
                    assert(next_tail == 0nat);
                    assert(head > 0nat); // since next_tail != head
                    // pre range: head <= tail always (head < len = tail+1), so pre: head <= i < tail
                    assert(head <= tail); // head < len = tail+1, so head <= tail
                    // post range: head > 0 = next_tail, else: i >= head || i < 0 = i >= head
                    // For i != tail = len-1 and 0 <= i < len:
                    //   pre range: head <= i < len-1
                    //   post range: i >= head
                    //   For i < len-1: both are i >= head. Equal!
                    assert(i < len - 1);
                } else {
                    assert(next_tail == tail + 1);
                    if head <= tail {
                        // head <= tail < tail+1 = next_tail -> head <= next_tail
                        // pre range: head <= i < tail
                        // post range: head <= i < tail+1
                        // for i != tail: i < tail+1 iff i < tail (for integer i)
                    } else if head == next_tail {
                        // excluded since next_tail != head
                        assert(false);
                    } else {
                        // head > next_tail = tail+1 > tail
                        // pre range: i >= head || i < tail
                        // post range: i >= head || i < tail+1
                        // for i != tail: i < tail+1 iff i < tail (integers)
                    }
                }
            };
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i)) by {
                assert(i != tail);
            };
            if !post.is_checked_out(i) {
                assert(post.storage.index(i) == pre.storage.index(i)) by {
                    assert(i != tail);
                };
            }
        }
    };
}
#[inductive(consume_start)]
fn consume_start_inductive(pre: Self, post: Self) {
    let head = pre.consumer.get_Idle_0();
    assert forall |i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // consumer_post = Consuming(head) -> is_checked_out = true
            assert(post.consumer == ConsumerState::Consuming(head));
            assert(post.is_checked_out(head));
            // storage was withdrawn at head
            assert(!post.storage.dom().contains(head));
        } else {
            assert(pre.valid_storage_at_idx(i));
            // consumer_pre = Idle(head) -> never Consuming(i)
            // consumer_post = Consuming(head), i != head -> not Consuming(i)
            // producer unchanged
            assert(post.is_checked_out(i) == pre.is_checked_out(i)) by {
                assert(pre.consumer == ConsumerState::Idle(head));
                assert(post.consumer == ConsumerState::Consuming(head));
                assert(post.producer == pre.producer);
                // consumer_pre: Idle != Consuming
                // consumer_post: Consuming(head) != Consuming(i) since i != head
                assert(i != head);
            };
            assert(post.in_active_range(i) == pre.in_active_range(i)) by {
                assert(post.head == pre.head);
                assert(post.tail == pre.tail);
            };
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i)) by {
                assert(i != head);
            };
            if !post.is_checked_out(i) {
                assert(post.storage.index(i) == pre.storage.index(i)) by {
                    assert(i != head);
                };
            }
        }
    };
}
#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());
    let len = pre.len();
    let tail = pre.tail;
    assert forall |i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // is_checked_out_post(head): consumer_post = Idle(next_head), producer_post = producer_pre
            // producer_pre != Producing(head) (from not_overlapping: head != tail when Producing)
            assert(!post.is_checked_out(head)) by {
                assert(post.consumer == ConsumerState::Idle(next_head));
                assert(post.producer == pre.producer);
                assert(pre.not_overlapping());
                match pre.producer {
                    ProducerState::Idle(_t) => {}
                    ProducerState::Producing(t) => {
                        // not_overlapping: head != t
                        assert(head != t);
                    }
                }
            };
            // in_active_range_post(head) = false
            // post.head = next_head, post.tail = tail
            assert(!post.in_active_range(head)) by {
                assert(post.head == next_head);
                assert(post.tail == tail);
                assert(0 <= head < len);
                assert(0 <= tail < len);
                if head + 1 == len {
                    // next_head = 0
                    assert(next_head == 0nat);
                    // post.head = 0, post.tail = tail
                    // post.head <= post.tail always (0 <= tail)
                    // active: 0 <= i < tail. Is head = len-1 in this? head < tail? len-1 < tail impossible.
                    assert(head >= tail || head == tail);
                    // Actually: post active range = [0, tail)
                    // head = len-1 in [0, tail)? need 0 <= len-1 < tail, but tail < len, so impossible
                    assert(!(head >= 0nat && head < tail)) by {
                        // head = len-1 >= tail? Not necessarily. But head >= tail means head not in [head+1, tail)
                        // If head < tail: then tail > len-1, impossible since tail < len
                    };
                } else {
                    // next_head = head+1
                    assert(next_head == head + 1);
                    if next_head <= tail {
                        // active: next_head <= i < tail. Is head in this? head < next_head = head+1 => head < head+1 true but head >= head+1 needed. Contradiction.
                        assert(!(head >= next_head && head < tail)) by {
                            assert(head < next_head);
                        };
                    } else {
                        // active: i >= next_head || i < tail. Is head in this?
                        // head >= next_head = head+1? No.
                        // head < tail? If so, then tail > head, but next_head = head+1 > tail means head >= tail. Contradiction.
                        assert(head >= tail);
                        assert(!(head >= next_head || head < tail)) by {
                            assert(head < next_head);
                            assert(head >= tail);
                        };
                    }
                }
            };
        } else {
            assert(pre.valid_storage_at_idx(i));
            assert(post.is_checked_out(i) == pre.is_checked_out(i)) by {
                assert(pre.consumer == ConsumerState::Consuming(head));
                assert(post.consumer == ConsumerState::Idle(next_head));
                assert(post.producer == pre.producer);
                // consumer_pre: Consuming(head), i != head -> not Consuming(i)
                // consumer_post: Idle -> not Consuming(i)
                assert(i != head);
            };
            assert(post.in_active_range(i) == pre.in_active_range(i)) by {
                // head changes from head_val to next_head, tail unchanged
                assert(post.head == next_head);
                assert(post.tail == tail);
                assert(pre.head == head);
                assert(pre.tail == tail);
                assert(i != head);
                assert(0 <= i < len);
                assert(0 <= head < len);
                assert(0 <= tail < len);
                if head + 1 == len {
                    assert(next_head == 0nat);
                    // post.head = 0, post.tail = tail
                    // post.head <= post.tail always
                    // pre range: head <= tail? head = len-1, tail < len, so tail = len-1 = head possible
                    // but head != tail (from consume_start require), so pre.head != pre.tail
                    // If pre.head > pre.tail: pre range: i >= head=len-1 || i < tail
                    //   = (i == len-1) || i < tail
                    // For i != head=len-1: pre range = i < tail
                    // Post range: 0 <= i < tail (since next_head = 0)
                    // For i != len-1: i < tail iff i < tail. Equal!
                    // But wait: pre.head = len-1, could pre.head <= pre.tail?
                    // pre.head <= pre.tail means len-1 <= pre.tail, so pre.tail = len-1 = pre.head.
                    // But from in_bounds pre, pre.head == head from consumer = Consuming(head).
                    // And pre.head != pre.tail (since pre.consumer was Idle(head) with head != tail in consume_start).
                    // Wait, we're in consume_end now. Pre has consumer = Consuming(head).
                    // The consume_start required head != tail. But we're in consume_end now.
                    // Actually we don't directly have head != tail here.
                    // Hmm, but we need this for the proof.
                    // Actually: pre.head = head (from in_bounds), pre.tail = tail.
                    // Could head == tail? We need to handle both cases.
                    if head <= tail {
                        // pre.head = len-1 <= tail, so tail = len-1 = head. 
                        // But if head == tail, pre active range = empty (no element).
                        // head + 1 = len, so next_head = 0.
                        // i != head means i != len-1.
                        // pre range: head <= tail means head <= i < tail = head -> empty. So pre range = false.
                        // post range: next_head = 0 <= tail. 0 <= i < tail = head = len-1. i < len-1 = head.
                        // For i != head = len-1, and i < len: i < len-1 is possible.
                        // Hmm, this might not be equal...
                        // Wait: if head == tail, then pre active range is empty (head <= i < tail = head is false).
                        // post active range: next_head=0, tail_post=tail=head=len-1. 0 <= i < head.
                        // For i != head: could i < head = len-1 be true? Yes.
                        // But pre range is empty (false)!
                        // This would be a contradiction unless len=1.
                        // Actually if head == tail (== len-1), then the buffer is empty.
                        // But we're in consume_end, which follows consume_start where we required head != tail.
                        // So when we reach consume_end, we know there WAS an element. But by the time we're here,
                        // consumer = Consuming(head) and this is the post state after consuming.
                        // Hmm, but we don't have the constraint head != tail here.
                        // Actually wait: from the pre invariant not_overlapping:
                        // consumer = Consuming(head), so the match:
                        // (Idle(tail'), Consuming(head)) -> head != tail'
                        // (Producing(tail'), Consuming(head)) -> head != tail' && ...
                        // So head != tail always when consumer = Consuming(head)!
                        // Because not_overlapping guarantees this.
                        assert(false) by {
                            // head == tail contradicts not_overlapping:
                            // (producer, Consuming(head)) always requires head != producer's tail
                            // And pre.tail == producer's tail (from in_bounds)
                            assert(pre.not_overlapping());
                            match pre.producer {
                                ProducerState::Idle(t) => {
                                    assert(head != t);
                                    assert(t == tail);
                                    assert(head != tail);
                                }
                                ProducerState::Producing(t) => {
                                    assert(head != t);
                                    assert(t == tail);
                                    assert(head != tail);
                                }
                            }
                        };
                    } else {
                        // pre.head > pre.tail: head = len-1 > tail
                        // pre range: i >= head=len-1 || i < tail
                        // For i != head=len-1: pre range = i < tail
                        // post range: next_head=0 <= tail, 0 <= i < tail
                        // Equal: both are i < tail (for 0 <= i < len and i != len-1)
                    }
                } else {
                    assert(next_head == head + 1);
                    if head < tail {
                        // pre: head <= tail, range: head <= i < tail
                        // post: next_head = head+1, head+1 <= tail (since head < tail),
                        //   post range: head+1 <= i < tail
                        // For i != head: i >= head iff i >= head+1 (integers). So i >= head && i < tail iff i >= head+1 && i < tail.
                    } else {
                        // head > tail (we know head != tail from not_overlapping above, but let's be safe)
                        // Could head == tail? From not_overlapping_pre, no (same argument as above).
                        // head > tail:
                        // pre: i >= head || i < tail
                        // next_head = head+1
                        // If head+1 <= tail: post range: head+1 <= i < tail
                        //   But head > tail and head+1 <= tail means head >= tail, and head+1 > tail. Contradiction (head+1 <= tail requires head < tail).
                        //   Actually wait: head > tail and head + 1 <= tail means head >= tail, combined gives head == tail (impossible, from not_overlapping) or... no. If head > tail, then head >= tail+1, so head+1 >= tail+2 > tail. So head+1 > tail always when head > tail. So next_head = head+1 > tail.
                        // post range (head+1 > tail): else branch: i >= head+1 || i < tail
                        // pre range (head > tail): i >= head || i < tail
                        // For i != head: i >= head iff i >= head+1. Equal!
                        assert(head > tail) by {
                            assert(pre.not_overlapping());
                            match pre.producer {
                                ProducerState::Idle(t) => {
                                    assert(head != t);
                                    assert(t == tail);
                                    assert(head != tail);
                                }
                                ProducerState::Producing(t) => {
                                    assert(head != t);
                                    assert(t == tail);
                                    assert(head != tail);
                                }
                            }
                        };
                    }
                }
            };
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i)) by {
                assert(i != head);
            };
            if !post.is_checked_out(i) {
                assert(post.storage.index(i) == pre.storage.index(i)) by {
                    assert(i != head);
                };
            }
        }
    };
}

